//! Les versions, une entrée par version du changelog.
//!
//! Des données, pas du balisage : `crate::doc` est le seul rendu, et une
//! traduction manquante ne compile pas.
//!
//! Les mesures que la page cite sont celles que chaque version a publiées :
//! elles sont datées par la version qui les a annoncées, et ne se rafraîchissent
//! pas quand une version suivante les fait bouger.

use crate::doc::{Block, Doc, Tone};

