/// section datée dans CHANGELOG.md, pour que la page ne puisse pas prendre du
/// retard sur le dépôt en silence.
pub const RELEASED_VERSIONS: &[&str] = &["0.4.0", "0.3.0", "0.2.0", "0.1.1", "0.1.0"];

